194|/* Read data, and (optionally) run it through the CRC. */
195|void /* PRIVATE */
196|png_crc_read(png_structrp png_ptr, png_bytep buf, png_uint_32 length)
197|{
198|   if (png_ptr == NULL)
199|      return;
200|
201|   png_read_data(png_ptr, buf, length);
202|   png_calculate_crc(png_ptr, buf, length);
