652|         if (ret == Z_STREAM_END)
653|         {
654|            /* Use 'inflateReset' here, not 'inflateReset2' because this
655|             * preserves the previously decided window size (otherwise it would
656|             * be necessary to store the previous window size.)  In practice
657|             * this doesn't matter anyway, because png_inflate will call inflate
658|             * with Z_FINISH in almost all cases, so the window will not be
659|             * maintained.
660|             */
661|            if (inflateReset(&png_ptr->zstream) == Z_OK)
662|            {
663|               /* Because of the limit checks above we know that the new,
664|                * expanded, size will fit in a size_t (let alone an
665|                * png_alloc_size_t).  Use png_malloc_base here to avoid an
666|                * extra OOM message.
667|                */
668|               png_alloc_size_t new_size = *newlength;
669|               png_alloc_size_t buffer_size = prefix_size + new_size +
670|                   (terminate != 0);
671|               png_bytep text = png_voidcast(png_bytep, png_malloc_base(png_ptr,
672|                   buffer_size));
673|               /* attempt to stop an oss-fuzz "use of uninitialized value"
674|                * in png_set_text_2() and png_icc_check_tag_table()
675|                */
676|               memset(text, 0, buffer_size);
677|
678|               if (text != NULL)
679|               {
680|                  ret = png_inflate(png_ptr, png_ptr->chunk_name, 1/*finish*/,
681|                      png_ptr->read_buffer + prefix_size, &lzsize,
682|                      text + prefix_size, newlength);
683|
684|                  if (ret == Z_STREAM_END)
685|                  {
686|                     if (new_size == *newlength)
687|                     {
688|                        if (terminate != 0)
689|                           text[prefix_size + *newlength] = 0;
690|
691|                        if (prefix_size > 0)
692|                           memcpy(text, png_ptr->read_buffer, prefix_size);
693|
694|                        {
695|                           png_bytep old_ptr = png_ptr->read_buffer;
696|
697|                           png_ptr->read_buffer = text;
698|                           png_ptr->read_buffer_size = buffer_size;
699|                           text = old_ptr; /* freed below */
700|                        }
701|                     }
702|
703|                     else
704|                     {
705|                        /* The size changed on the second read, there can be no
706|                         * guarantee that anything is correct at this point.
707|                         * The 'msg' pointer has been set to "unexpected end of
708|                         * LZ stream", which is fine, but return an error code
709|                         * that the caller won't accept.
710|                         */
711|                        ret = PNG_UNEXPECTED_ZLIB_RETURN;
712|                     }
713|                  }
714|
715|                  else if (ret == Z_OK)
716|                     ret = PNG_UNEXPECTED_ZLIB_RETURN; /* for safety */
717|
718|                  /* Free the text pointer (this is the old read_buffer on
719|                   * success)
720|                   */
721|                  png_free(png_ptr, text);
722|
723|                  /* This really is very benign, but it's still an error because
724|                   * the extra space may otherwise be used as a Trojan Horse.
725|                   */
726|                  if (ret == Z_STREAM_END &&
727|                      chunklength - prefix_size != lzsize)
728|                     png_chunk_benign_error(png_ptr, "extra compressed data");
729|               }
730|
731|               else
732|               {
733|                  /* Out of memory allocating the buffer */
734|                  ret = Z_MEM_ERROR;
735|                  png_zstream_error(png_ptr, Z_MEM_ERROR);
736|               }
737|            }
738|
739|            else
740|            {
741|               /* inflateReset failed, store the error message */
742|               png_zstream_error(png_ptr, ret);
743|
744|               if (ret == Z_STREAM_END)
745|                  ret = PNG_UNEXPECTED_ZLIB_RETURN;
746|            }
747|         }
748|
749|         else if (ret == Z_OK)
750|            ret = PNG_UNEXPECTED_ZLIB_RETURN;
751|
752|         /* Release the claimed stream */
753|         png_ptr->zowner = 0;
754|      }
755|
756|      else /* the claim failed */ if (ret == Z_STREAM_END) /* impossible! */
757|         ret = PNG_UNEXPECTED_ZLIB_RETURN;
758|
759|      return ret;
760|   }
761|
762|   else
763|   {
764|      /* Application/configuration limits exceeded */
765|      png_zstream_error(png_ptr, Z_MEM_ERROR);
766|      return Z_MEM_ERROR;
767|   }
