4138|#ifdef PNG_SEQUENTIAL_READ_SUPPORTED
4139|void /* PRIVATE */
4140|png_read_IDAT_data(png_structrp png_ptr, png_bytep output,
4141|    png_alloc_size_t avail_out)
4142|{
4143|   /* Loop reading IDATs and decompressing the result into output[avail_out] */
4144|   png_ptr->zstream.next_out = output;
4145|   png_ptr->zstream.avail_out = 0; /* safety: set below */
4146|
4147|   if (output == NULL)
4148|      avail_out = 0;
4149|
4150|   do
4151|   {
4152|      int ret;
4153|      png_byte tmpbuf[PNG_INFLATE_BUF_SIZE];
4154|
4155|      if (png_ptr->zstream.avail_in == 0)
4156|      {
4157|         uInt avail_in;
4158|         png_bytep buffer;
4159|
4160|         while (png_ptr->idat_size == 0)
4161|         {
4162|            png_crc_finish(png_ptr, 0);
4163|
4164|            png_ptr->idat_size = png_read_chunk_header(png_ptr);
4165|            /* This is an error even in the 'check' case because the code just
4166|             * consumed a non-IDAT header.
4167|             */
4168|            if (png_ptr->chunk_name != png_IDAT)
4169|               png_error(png_ptr, "Not enough image data");
4170|         }
4171|
4172|         avail_in = png_ptr->IDAT_read_size;
4173|
4174|         if (avail_in > png_ptr->idat_size)
4175|            avail_in = (uInt)png_ptr->idat_size;
4176|
4177|         /* A PNG with a gradually increasing IDAT size will defeat this attempt
4178|          * to minimize memory usage by causing lots of re-allocs, but
4179|          * realistically doing IDAT_read_size re-allocs is not likely to be a
4180|          * big problem.
4181|          */
4182|         buffer = png_read_buffer(png_ptr, avail_in, 0/*error*/);
4183|
4184|         png_crc_read(png_ptr, buffer, avail_in);
4185|         png_ptr->idat_size -= avail_in;
4186|
4187|         png_ptr->zstream.next_in = buffer;
4188|         png_ptr->zstream.avail_in = avail_in;
4189|      }
4190|
4191|      /* And set up the output side. */
4192|      if (output != NULL) /* standard read */
4193|      {
4194|         uInt out = ZLIB_IO_MAX;
4195|
4196|         if (out > avail_out)
4197|            out = (uInt)avail_out;
4198|
4199|         avail_out -= out;
4200|         png_ptr->zstream.avail_out = out;
4201|      }
4202|
4203|      else /* after last row, checking for end */
4204|      {
4205|         png_ptr->zstream.next_out = tmpbuf;
4206|         png_ptr->zstream.avail_out = (sizeof tmpbuf);
4207|      }
4208|
4209|      /* Use NO_FLUSH; this gives zlib the maximum opportunity to optimize the
4210|       * process.  If the LZ stream is truncated the sequential reader will
4211|       * terminally damage the stream, above, by reading the chunk header of the
4212|       * following chunk (it then exits with png_error).
4213|       *
4214|       * TODO: deal more elegantly with truncated IDAT lists.
4215|       */
4216|      ret = PNG_INFLATE(png_ptr, Z_NO_FLUSH);
4217|
4218|      /* Take the unconsumed output back. */
4219|      if (output != NULL)
4220|         avail_out += png_ptr->zstream.avail_out;
4221|
4222|      else /* avail_out counts the extra bytes */
4223|         avail_out += (sizeof tmpbuf) - png_ptr->zstream.avail_out;
4224|
4225|      png_ptr->zstream.avail_out = 0;
4226|
4227|      if (ret == Z_STREAM_END)
4228|      {
4229|         /* Do this for safety; we won't read any more into this row. */
4230|         png_ptr->zstream.next_out = NULL;
4231|
4232|         png_ptr->mode |= PNG_AFTER_IDAT;
4233|         png_ptr->flags |= PNG_FLAG_ZSTREAM_ENDED;
4234|
4235|         if (png_ptr->zstream.avail_in > 0 || png_ptr->idat_size > 0)
4236|            png_chunk_benign_error(png_ptr, "Extra compressed data");
4237|         break;
4238|      }
4239|
4240|      if (ret != Z_OK)
4241|      {
4242|         png_zstream_error(png_ptr, ret);
4243|
4244|         if (output != NULL)
4245|            png_chunk_error(png_ptr, png_ptr->zstream.msg);
4246|
4247|         else /* checking */
4248|         {
4249|            png_chunk_benign_error(png_ptr, png_ptr->zstream.msg);
4250|            return;
4251|         }
4252|      }
4253|   } while (avail_out > 0);
4254|
4255|   if (avail_out > 0)
4256|   {
4257|      /* The stream ended before the image; this is the same as too few IDATs so
4258|       * should be handled the same way.
4259|       */
4260|      if (output != NULL)
4261|         png_error(png_ptr, "Not enough image data");
4262|
4263|      else /* the deflate stream contained extra data */
4264|         png_chunk_benign_error(png_ptr, "Too much image data");
4265|   }
