4268|void /* PRIVATE */
4269|png_read_finish_IDAT(png_structrp png_ptr)
4270|{
4271|   /* We don't need any more data and the stream should have ended, however the
4272|    * LZ end code may actually not have been processed.  In this case we must
4273|    * read it otherwise stray unread IDAT data or, more likely, an IDAT chunk
4274|    * may still remain to be consumed.
4275|    */
4276|   if ((png_ptr->flags & PNG_FLAG_ZSTREAM_ENDED) == 0)
4277|   {
4278|      /* The NULL causes png_read_IDAT_data to swallow any remaining bytes in
4279|       * the compressed stream, but the stream may be damaged too, so even after
4280|       * this call we may need to terminate the zstream ownership.
4281|       */
4282|      png_read_IDAT_data(png_ptr, NULL, 0);
4283|      png_ptr->zstream.next_out = NULL; /* safety */
4284|
4285|      /* Now clear everything out for safety; the following may not have been
4286|       * done.
4287|       */
4288|      if ((png_ptr->flags & PNG_FLAG_ZSTREAM_ENDED) == 0)
4289|      {
4290|         png_ptr->mode |= PNG_AFTER_IDAT;
4291|         png_ptr->flags |= PNG_FLAG_ZSTREAM_ENDED;
4292|      }
4293|   }
4294|
4295|   /* If the zstream has not been released do it now *and* terminate the reading
4296|    * of the final IDAT chunk.
4297|    */
4298|   if (png_ptr->zowner == png_IDAT)
4299|   {
4300|      /* Always do this; the pointers otherwise point into the read buffer. */
4301|      png_ptr->zstream.next_in = NULL;
4302|      png_ptr->zstream.avail_in = 0;
4303|
4304|      /* Now we no longer own the zstream. */
4305|      png_ptr->zowner = 0;
4306|
4307|      /* The slightly weird semantics of the sequential IDAT reading is that we
4308|       * are always in or at the end of an IDAT chunk, so we always need to do a
4309|       * crc_finish here.  If idat_size is non-zero we also need to read the
4310|       * spurious bytes at the end of the chunk now.
4311|       */
4312|      (void)png_crc_finish(png_ptr, png_ptr->idat_size);
4313|   }
