4323|
4324|   /* Offset to next interlace block */
4325|   static PNG_CONST png_byte png_pass_inc[7] = {8, 8, 4, 4, 2, 2, 1};
4326|
4327|   /* Start of interlace block in the y direction */
4328|   static PNG_CONST png_byte png_pass_ystart[7] = {0, 0, 4, 0, 2, 0, 1};
4329|
4330|   /* Offset to next interlace block in the y direction */
