773|#ifdef PNG_READ_iCCP_SUPPORTED
774|/* Perform a partial read and decompress, producing 'avail_out' bytes and
775| * reading from the current chunk as required.
776| */
777|static int
778|png_inflate_read(png_structrp png_ptr, png_bytep read_buffer, uInt read_size,
779|    png_uint_32p chunk_bytes, png_bytep next_out, png_alloc_size_t *out_size,
780|    int finish)
781|{
782|   if (png_ptr->zowner == png_ptr->chunk_name)
783|   {
784|      int ret;
785|
786|      /* next_in and avail_in must have been initialized by the caller. */
787|      png_ptr->zstream.next_out = next_out;
788|      png_ptr->zstream.avail_out = 0; /* set in the loop */
789|
790|      do
791|      {
792|         if (png_ptr->zstream.avail_in == 0)
793|         {
794|            if (read_size > *chunk_bytes)
795|               read_size = (uInt)*chunk_bytes;
796|            *chunk_bytes -= read_size;
797|
798|            if (read_size > 0)
799|               png_crc_read(png_ptr, read_buffer, read_size);
800|
801|            png_ptr->zstream.next_in = read_buffer;
802|            png_ptr->zstream.avail_in = read_size;
803|         }
804|
805|         if (png_ptr->zstream.avail_out == 0)
806|         {
807|            uInt avail = ZLIB_IO_MAX;
808|            if (avail > *out_size)
809|               avail = (uInt)*out_size;
810|            *out_size -= avail;
811|
812|            png_ptr->zstream.avail_out = avail;
813|         }
814|
815|         /* Use Z_SYNC_FLUSH when there is no more chunk data to ensure that all
816|          * the available output is produced; this allows reading of truncated
817|          * streams.
818|          */
819|         ret = PNG_INFLATE(png_ptr, *chunk_bytes > 0 ?
820|             Z_NO_FLUSH : (finish ? Z_FINISH : Z_SYNC_FLUSH));
821|      }
822|      while (ret == Z_OK && (*out_size > 0 || png_ptr->zstream.avail_out > 0));
823|
824|      *out_size += png_ptr->zstream.avail_out;
825|      png_ptr->zstream.avail_out = 0; /* Should not be required, but is safe */
826|
827|      /* Ensure the error message pointer is always set: */
828|      png_zstream_error(png_ptr, ret);
829|      return ret;
830|   }
831|
832|   else
833|   {
834|      png_ptr->zstream.msg = PNGZ_MSG_CAST("zstream unclaimed");
835|      return Z_STREAM_ERROR;
836|   }
837|}
838|#endif /* READ_iCCP */
