4140|void /* PRIVATE */
4141|png_read_IDAT_data(png_structrp png_ptr, png_bytep output,
4142|    png_alloc_size_t avail_out)
4143|{
4144|   /* Loop reading IDATs and decompressing the result into output[avail_out] */
4145|   png_ptr->zstream.next_out = output;
4146|   png_ptr->zstream.avail_out = 0; /* safety: set below */
4147|
4148|   if (output == NULL)
4149|      avail_out = 0;
4150|
4151|   do
4152|   {
4153|      int ret;
4154|      png_byte tmpbuf[PNG_INFLATE_BUF_SIZE];
4155|
4156|      if (png_ptr->zstream.avail_in == 0)
4157|      {
4158|         uInt avail_in;
4159|         png_bytep buffer;
4160|
4161|         while (png_ptr->idat_size == 0)
4162|         {
4163|            png_crc_finish(png_ptr, 0);
4164|
4165|            png_ptr->idat_size = png_read_chunk_header(png_ptr);
4166|            /* This is an error even in the 'check' case because the code just
4167|             * consumed a non-IDAT header.
4168|             */
4169|            if (png_ptr->chunk_name != png_IDAT)
4170|               png_error(png_ptr, "Not enough image data");
4171|         }
4172|
4173|         avail_in = png_ptr->IDAT_read_size;
4174|
4175|         if (avail_in > png_ptr->idat_size)
4176|            avail_in = (uInt)png_ptr->idat_size;
4177|
4178|         /* A PNG with a gradually increasing IDAT size will defeat this attempt
4179|          * to minimize memory usage by causing lots of re-allocs, but
4180|          * realistically doing IDAT_read_size re-allocs is not likely to be a
4181|          * big problem.
4182|          */
4183|         buffer = png_read_buffer(png_ptr, avail_in, 0/*error*/);
4184|
4185|         png_crc_read(png_ptr, buffer, avail_in);
4186|         png_ptr->idat_size -= avail_in;
4187|
4188|         png_ptr->zstream.next_in = buffer;
4189|         png_ptr->zstream.avail_in = avail_in;
4190|      }
4191|
4192|      /* And set up the output side. */
4193|      if (output != NULL) /* standard read */
4194|      {
4195|         uInt out = ZLIB_IO_MAX;
4196|
4197|         if (out > avail_out)
4198|            out = (uInt)avail_out;
4199|
4200|         avail_out -= out;
4201|         png_ptr->zstream.avail_out = out;
4202|      }
4203|
4204|      else /* after last row, checking for end */
4205|      {
4206|         png_ptr->zstream.next_out = tmpbuf;
4207|         png_ptr->zstream.avail_out = (sizeof tmpbuf);
4208|      }
4209|
4210|      /* Use NO_FLUSH; this gives zlib the maximum opportunity to optimize the
4211|       * process.  If the LZ stream is truncated the sequential reader will
4212|       * terminally damage the stream, above, by reading the chunk header of the
4213|       * following chunk (it then exits with png_error).
4214|       *
4215|       * TODO: deal more elegantly with truncated IDAT lists.
4216|       */
4217|      ret = PNG_INFLATE(png_ptr, Z_NO_FLUSH);
4218|
4219|      /* Take the unconsumed output back. */
4220|      if (output != NULL)
4221|         avail_out += png_ptr->zstream.avail_out;
4222|
4223|      else /* avail_out counts the extra bytes */
4224|         avail_out += (sizeof tmpbuf) - png_ptr->zstream.avail_out;
4225|
4226|      png_ptr->zstream.avail_out = 0;
4227|
4228|      if (ret == Z_STREAM_END)
4229|      {
4230|         /* Do this for safety; we won't read any more into this row. */
4231|         png_ptr->zstream.next_out = NULL;
4232|
4233|         png_ptr->mode |= PNG_AFTER_IDAT;
4234|         png_ptr->flags |= PNG_FLAG_ZSTREAM_ENDED;
4235|
4236|         if (png_ptr->zstream.avail_in > 0 || png_ptr->idat_size > 0)
4237|            png_chunk_benign_error(png_ptr, "Extra compressed data");
4238|         break;
4239|      }
4240|
4241|      if (ret != Z_OK)
4242|      {
4243|         png_zstream_error(png_ptr, ret);
4244|
4245|         if (output != NULL)
4246|            png_chunk_error(png_ptr, png_ptr->zstream.msg);
4247|
4248|         else /* checking */
4249|         {
4250|            png_chunk_benign_error(png_ptr, png_ptr->zstream.msg);
4251|            return;
4252|         }
4253|      }
4254|   } while (avail_out > 0);
4255|
4256|   if (avail_out > 0)
4257|   {
4258|      /* The stream ended before the image; this is the same as too few IDATs so
4259|       * should be handled the same way.
4260|       */
4261|      if (output != NULL)
4262|         png_error(png_ptr, "Not enough image data");
4263|
4264|      else /* the deflate stream contained extra data */
4265|         png_chunk_benign_error(png_ptr, "Too much image data");
4266|   }
