4269|void /* PRIVATE */
4270|png_read_finish_IDAT(png_structrp png_ptr)
4271|{
4272|   /* We don't need any more data and the stream should have ended, however the
4273|    * LZ end code may actually not have been processed.  In this case we must
4274|    * read it otherwise stray unread IDAT data or, more likely, an IDAT chunk
4275|    * may still remain to be consumed.
4276|    */
4277|   if ((png_ptr->flags & PNG_FLAG_ZSTREAM_ENDED) == 0)
4278|   {
4279|      /* The NULL causes png_read_IDAT_data to swallow any remaining bytes in
4280|       * the compressed stream, but the stream may be damaged too, so even after
4281|       * this call we may need to terminate the zstream ownership.
4282|       */
4283|      png_read_IDAT_data(png_ptr, NULL, 0);
4284|      png_ptr->zstream.next_out = NULL; /* safety */
4285|
4286|      /* Now clear everything out for safety; the following may not have been
4287|       * done.
4288|       */
4289|      if ((png_ptr->flags & PNG_FLAG_ZSTREAM_ENDED) == 0)
4290|      {
4291|         png_ptr->mode |= PNG_AFTER_IDAT;
4292|         png_ptr->flags |= PNG_FLAG_ZSTREAM_ENDED;
4293|      }
4294|   }
4295|
4296|   /* If the zstream has not been released do it now *and* terminate the reading
4297|    * of the final IDAT chunk.
4298|    */
4299|   if (png_ptr->zowner == png_IDAT)
4300|   {
4301|      /* Always do this; the pointers otherwise point into the read buffer. */
4302|      png_ptr->zstream.next_in = NULL;
4303|      png_ptr->zstream.avail_in = 0;
4304|
4305|      /* Now we no longer own the zstream. */
4306|      png_ptr->zowner = 0;
4307|
4308|      /* The slightly weird semantics of the sequential IDAT reading is that we
4309|       * are always in or at the end of an IDAT chunk, so we always need to do a
4310|       * crc_finish here.  If idat_size is non-zero we also need to read the
4311|       * spurious bytes at the end of the chunk now.
4312|       */
4313|      (void)png_crc_finish(png_ptr, png_ptr->idat_size);
4314|   }
